#!/usr/bin/env python3
"""Cloud-only exact-source OBS browser experiment; never changes installed product."""
import os,sys,platform,pathlib,hashlib,json,difflib,subprocess
assert os.environ.get("GITHUB_ACTIONS") == "true" and platform.system() == "Darwin"
assert platform.machine() == "arm64"
root=pathlib.Path(sys.argv[1]).resolve()
out=pathlib.Path(os.environ["AI_LIVE_OBS_COPY_EVIDENCE"]).resolve()
out.mkdir(parents=True,exist_ok=True)
assert subprocess.check_output(["git","-C",str(root),"rev-parse","HEAD"],text=True).strip()=="ba2f32bdf791005443988a4955e963663e16b1ed"
browser=root/"plugins/obs-browser"
assert subprocess.check_output(["git","-C",str(browser),"rev-parse","HEAD"],text=True).strip()=="3f0a2cdf378939ebe3c6f9ab36d4ea100c25aac2"
edits=json.loads("[{\"file\":\"obs-browser-source.hpp\",\"blob\":\"5bf26b5ceefc83df75ff3ccfa19fd930e8fc74ca\",\"old\":\"extern bool hwaccel;\",\"new\":\"extern bool hwaccel;\\n// ISOLATED CLOUD EXPERIMENT ONLY: protected by the OBS graphics lock.\\nextern bool ci_owned_copy_enabled;\\nextern uint64_t ci_accelerated_paints, ci_owned_copies, ci_owned_copy_failures;\"},{\"file\":\"obs-browser-source.hpp\",\"blob\":\"5bf26b5ceefc83df75ff3ccfa19fd930e8fc74ca\",\"old\":\"\\tgs_texture_t *extra_texture = nullptr;\",\"new\":\"\\tgs_texture_t *extra_texture = nullptr;\\n\\tgs_stagesurf_t *ci_copy_completion = nullptr;\\n\\tbool ci_texture_owned = false;\"},{\"file\":\"obs-browser-source.hpp\",\"blob\":\"5bf26b5ceefc83df75ff3ccfa19fd930e8fc74ca\",\"old\":\"\\t\\tobs_enter_graphics();\\n\\t\\tif (extra_texture) {\",\"new\":\"\\t\\tobs_enter_graphics();\\n\\t\\tif (ci_copy_completion) {\\n\\t\\t\\tgs_stagesurface_destroy(ci_copy_completion);\\n\\t\\t\\tci_copy_completion = nullptr;\\n\\t\\t}\\n\\t\\tci_texture_owned = false;\\n\\t\\tif (extra_texture) {\"},{\"file\":\"browser-client.cpp\",\"blob\":\"bf7baada99a04733923d0941d5302f5d16d61395\",\"old\":\"void BrowserClient::OnAcceleratedPaint(CefRefPtr<CefBrowser>, PaintElementType type, const RectList &,\",\"new\":\"#if defined(__APPLE__) && CHROME_VERSION_BUILD >= 6367\\n// Diagnostic-only conservative copy. The Metal stage operation waits for GPU\\n// completion (OBS 32.2.2 MetalDevice.stageTextureToBuffer), so CEF's pooled\\n// IOSurface is no longer referenced by pending reads when this callback returns.\\n// The extra staging copy is an experiment barrier, not a proposed optimized fix.\\nstatic bool CiCopyOwnedTexture(BrowserSource *bs, IOSurfaceRef surface)\\n{\\n\\tgs_texture_t *shared = gs_texture_create_from_iosurface(surface);\\n\\tif (!shared)\\n\\t\\treturn false;\\n\\tconst uint32_t width = gs_texture_get_width(shared);\\n\\tconst uint32_t height = gs_texture_get_height(shared);\\n\\tconst gs_color_format format = gs_texture_get_color_format(shared);\\n\\tif (!bs->ci_texture_owned || !bs->texture ||\\n\\t    gs_texture_get_width(bs->texture) != width ||\\n\\t    gs_texture_get_height(bs->texture) != height ||\\n\\t    gs_texture_get_color_format(bs->texture) != format) {\\n\\t\\tif (bs->texture)\\n\\t\\t\\tgs_texture_destroy(bs->texture);\\n\\t\\tbs->texture = gs_texture_create(width, height, format, 1, nullptr, 0);\\n\\t\\tbs->ci_texture_owned = true;\\n\\t}\\n\\tif (bs->ci_copy_completion &&\\n\\t    (gs_stagesurface_get_width(bs->ci_copy_completion) != width ||\\n\\t     gs_stagesurface_get_height(bs->ci_copy_completion) != height ||\\n\\t     gs_stagesurface_get_color_format(bs->ci_copy_completion) != format)) {\\n\\t\\tgs_stagesurface_destroy(bs->ci_copy_completion);\\n\\t\\tbs->ci_copy_completion = nullptr;\\n\\t}\\n\\tif (!bs->ci_copy_completion)\\n\\t\\tbs->ci_copy_completion = gs_stagesurface_create(width, height, format);\\n\\tconst bool ready = bs->texture && bs->ci_copy_completion;\\n\\tif (ready) {\\n\\t\\tgs_flush();\\n\\t\\tgs_copy_texture(bs->texture, shared);\\n\\t\\tgs_flush();\\n\\t\\tgs_stage_texture(bs->ci_copy_completion, bs->texture);\\n\\t}\\n\\tgs_texture_destroy(shared);\\n\\treturn ready;\\n}\\n#endif\\n\\nvoid BrowserClient::OnAcceleratedPaint(CefRefPtr<CefBrowser>, PaintElementType type, const RectList &,\"},{\"file\":\"browser-client.cpp\",\"blob\":\"bf7baada99a04733923d0941d5302f5d16d61395\",\"old\":\"\\tobs_enter_graphics();\\n\\n\\tif (bs->texture) {\\n#ifdef _WIN32\\n\\t\\t//gs_texture_release_sync(bs->texture, 0);\",\"new\":\"\\tobs_enter_graphics();\\n#if defined(__APPLE__) && CHROME_VERSION_BUILD >= 6367\\n\\t++ci_accelerated_paints;\\n\\tif (ci_owned_copy_enabled) {\\n\\t\\tif (CiCopyOwnedTexture(bs, (IOSurfaceRef)(uintptr_t)info.shared_texture_io_surface))\\n\\t\\t\\t++ci_owned_copies;\\n\\t\\telse {\\n\\t\\t\\t++ci_owned_copy_failures;\\n\\t\\t\\tblog(LOG_ERROR, \\\"[cloud-copy-experiment] Actual owned texture allocation/copy failed\\\");\\n\\t\\t}\\n\\t\\tUpdateExtraTexture();\\n\\t\\tobs_leave_graphics();\\n\\t\\treturn;\\n\\t}\\n\\tbs->ci_texture_owned = false;\\n#endif\\n\\n\\tif (bs->texture) {\\n#ifdef _WIN32\\n\\t\\t//gs_texture_release_sync(bs->texture, 0);\"},{\"file\":\"obs-browser-plugin.cpp\",\"blob\":\"95a168c6b1b6bd2d800165753dae2205f4829f15\",\"old\":\"void obs_module_post_load(void)\",\"new\":\"// ISOLATED CLOUD EXPERIMENT ONLY. The installed product is never patched.\\nbool ci_owned_copy_enabled = false;\\nuint64_t ci_accelerated_paints = 0, ci_owned_copies = 0, ci_owned_copy_failures = 0;\\n\\nvoid obs_module_post_load(void)\"},{\"file\":\"obs-browser-plugin.cpp\",\"blob\":\"95a168c6b1b6bd2d800165753dae2205f4829f15\",\"old\":\"\\tauto emit_event_request_cb = [](obs_data_t *request_data, obs_data_t *, void *) {\",\"new\":\"\\tauto copy_probe = [](obs_data_t *request, obs_data_t *response, void *) {\\n\\t\\tobs_enter_graphics();\\n\\t\\tci_owned_copy_enabled = obs_data_get_bool(request, \\\"enabled\\\");\\n\\t\\tif (obs_data_get_bool(request, \\\"reset\\\")) {\\n\\t\\t\\tci_accelerated_paints = ci_owned_copies = ci_owned_copy_failures = 0;\\n\\t\\t\\tblog(LOG_INFO, \\\"[cloud-copy-experiment] enabled=%s\\\",\\n\\t\\t\\t     ci_owned_copy_enabled ? \\\"true\\\" : \\\"false\\\");\\n\\t\\t}\\n\\t\\tobs_data_set_bool(response, \\\"enabled\\\", ci_owned_copy_enabled);\\n\\t\\tobs_data_set_int(response, \\\"acceleratedPaints\\\", ci_accelerated_paints);\\n\\t\\tobs_data_set_int(response, \\\"ownedCopies\\\", ci_owned_copies);\\n\\t\\tobs_data_set_int(response, \\\"copyFailures\\\", ci_owned_copy_failures);\\n\\t\\tobs_data_set_string(response, \\\"variant\\\", \\\"isolated-macos-owned-copy-32.2.2\\\");\\n\\t\\tobs_leave_graphics();\\n\\t};\\n\\tif (!obs_websocket_vendor_register_request(vendor, \\\"ci_owned_copy\\\", copy_probe, nullptr))\\n\\t\\tblog(LOG_ERROR, \\\"[cloud-copy-experiment] Cannot register diagnostic control\\\");\\n\\n\\tauto emit_event_request_cb = [](obs_data_t *request_data, obs_data_t *, void *) {\"}]")
originals={}
for edit in edits:
    p=browser/edit["file"]
    if edit["file"] not in originals:
        raw=p.read_bytes()
        blob=hashlib.sha1(("blob "+str(len(raw))+"\0").encode()+raw).hexdigest()
        assert blob==edit["blob"],(str(p),blob)
        originals[edit["file"]]=raw.decode()
    source=p.read_text()
    assert source.count(edit["old"])==1, edit["file"]
    p.write_text(source.replace(edit["old"],edit["new"]))
records=[]
for name,original in originals.items():
    current=(browser/name).read_text()
    records.append({"file":name,"originalGitBlob":next(x["blob"] for x in edits if x["file"]==name),"patchedSHA256":hashlib.sha256(current.encode()).hexdigest()})
    with (out/"exact-obs-browser-copy-experiment.patch").open("a") as f:
        f.write("".join(difflib.unified_diff(original.splitlines(True),current.splitlines(True),fromfile="a/"+name,tofile="b/"+name)))
(out/"source-provenance.json").write_text(json.dumps({"purpose":"unshipped isolated OBS plugin copy experiment","obsCommit":"ba2f32bdf791005443988a4955e963663e16b1ed","browserCommit":"3f0a2cdf378939ebe3c6f9ab36d4ea100c25aac2","files":records},indent=2))
print(json.dumps(records))
